import{_ as t,o,c as a,a2 as d}from"./chunks/framework.B8TleWq7.js";const p=JSON.parse('{"title":"Tooling and hooks","description":"","frontmatter":{},"headers":[],"relativePath":"guides/tooling.md","filePath":"guides/tooling.md"}'),r={name:"guides/tooling.md"};function n(i,e,s,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="tooling-and-hooks" tabindex="-1">Tooling and hooks <a class="header-anchor" href="#tooling-and-hooks" aria-label="Permalink to &quot;Tooling and hooks&quot;">​</a></h1><p>The development setup around the code: formatting, linting, editor support and how outside libraries are kept. The workflow is <strong>Script Sync and GitHub only</strong>: no Rojo, Rokit, Aftman or Wally.</p><p><strong>Principle:</strong> mechanical, repeated jobs (lookups, checks, formatting, reminders) are done by <strong>hooks</strong>, not by an AI assistant reading and reasoning each time. A hook runs on your PC and hands back only a short result.</p><h2 id="keel-install-and-the-guard-hook" tabindex="-1">Keel install and the guard hook <a class="header-anchor" href="#keel-install-and-the-guard-hook" aria-label="Permalink to &quot;Keel install and the guard hook&quot;">​</a></h2><p><code>tools/keel.js</code> installs and updates Keel in a game (see <a href="/Keel-Docs/getting-started/update-keel">Update Keel</a>). <strong><code>keel-guard</code></strong> (<code>.claude/hooks/keel-guard.js</code>, a PreToolUse hook on Write and Edit) refuses any edit to a file listed in <code>keel.json</code>, with a one-line reason pointing at the Keel repo. It does nothing where there is no <code>keel.json</code> (the Keel repo itself).</p><h2 id="place-attributes" tabindex="-1">Place attributes <a class="header-anchor" href="#place-attributes" aria-label="Permalink to &quot;Place attributes&quot;">​</a></h2><p>Attributes do not survive Script Sync, so these live in the place itself. Set them in the Properties panel. <strong>Every one has a default written in its script</strong> (read with <a href="/Keel-Docs/api/setting"><code>Setting.Get</code></a>), so the game behaves the same if the attribute is missing or has the wrong type. Remember to save the place after changing one.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>On</th><th>Meaning</th></tr></thead><tbody><tr><td><code>FastSpawn</code> (bool, default <code>false</code>)</td><td><code>ReplicatedStorage</code></td><td>Studio only: hide the loading screen as soon as the game has loaded</td></tr><tr><td><code>FreshData</code> (bool, default <code>false</code>)</td><td><code>ServerScriptService</code></td><td>Studio only: every player starts with brand-new data in a throwaway store</td></tr><tr><td><code>DataVersion</code> (number, default <code>1</code>)</td><td><code>ServerScriptService</code></td><td>Bump to 2, 3... to switch to a new empty player-data store (<code>PlayerData_Live_v2</code>). Old stores are kept</td></tr><tr><td><code>LogOff</code> (string, default empty)</td><td><code>ReplicatedStorage</code></td><td>Tags whose <code>Info</code> log lines are muted, comma separated. Followed live and replicated to clients</td></tr><tr><td><code>Version</code> (string, default <code>0.0.0</code>)</td><td><code>ReplicatedStorage</code></td><td>The build version, shown as a small <code>v&lt;version&gt;</code> label on every client</td></tr></tbody></table><h2 id="formatting-and-linting" tabindex="-1">Formatting and linting <a class="header-anchor" href="#formatting-and-linting" aria-label="Permalink to &quot;Formatting and linting&quot;">​</a></h2><ul><li><strong>StyLua</strong> formats Luau using <code>stylua.toml</code>: tabs, 120 columns, double quotes, always parentheses on calls.</li><li><strong>Selene</strong> lints using <code>selene.toml</code> (<code>std = &quot;roblox&quot;</code>).</li><li>The binaries come from the <strong>VS Code StyLua and Selene extensions</strong>.</li><li><strong>In VS Code:</strong> format on save is on for <code>.luau</code> and <code>.lua</code>.</li><li><strong>For Claude Code:</strong> a hook (<code>.claude/hooks/luau-check.js</code>) runs after every file Claude writes or edits. StyLua formats it, Selene lints it, and the type checker (<code>server.exe analyze</code> from the VS Code Luau extension) reports errors <strong>in the edited file</strong> only. Problems elsewhere never block an edit.</li></ul><h2 id="which-note-covers-which-file" tabindex="-1">Which note covers which file <a class="header-anchor" href="#which-note-covers-which-file" aria-label="Permalink to &quot;Which note covers which file&quot;">​</a></h2><p>Every note in <code>Docs/Systems/</code> lists the files it documents in a <code>code:</code> list in its frontmatter. A second hook (<code>.claude/hooks/note-lookup.js</code>) runs after every file Claude edits outside <code>Docs/</code> and names the notes that list that file, so only those need checking. It reads only the frontmatter, never the whole vault.</p><h2 id="editor-support-sourcemap" tabindex="-1">Editor support: sourcemap <a class="header-anchor" href="#editor-support-sourcemap" aria-label="Permalink to &quot;Editor support: sourcemap&quot;">​</a></h2><p>VS Code&#39;s Luau extension needs to know which file is which Studio instance, or it underlines correct code like <code>script.Parent.Vendor.Trove</code>. <strong><code>tools/sourcemap.js</code></strong> reads <code>src/</code> with Script Sync&#39;s naming rules and writes <code>sourcemap.json</code>; <code>.vscode/settings.json</code> tells luau-lsp to run it instead of Rojo. <code>sourcemap.json</code> is generated, so it is in <code>.gitignore</code>. If underlines come back after adding files, run <code>node tools/sourcemap.js</code> once, or reload VS Code.</p><p>It only knows scripts and folders from <code>src/</code>. Instances that exist only in Studio are unknown.</p><h2 id="vendored-libraries" tabindex="-1">Vendored libraries <a class="header-anchor" href="#vendored-libraries" aria-label="Permalink to &quot;Vendored libraries&quot;">​</a></h2><p>Outside libraries are copied into the repo, never installed by a package manager:</p><ul><li>They live in a <strong><code>Vendor/</code> folder</strong>. The Loader, <code>Defs.Boot</code> and <code>Entity.Boot</code> skip any Folder named <code>Vendor</code>, so a library is never booted as a module.</li><li>Each is an <strong>unchanged copy of one pinned commit</strong>. Only two things are added at the top: <code>--!nocheck</code> and <code>--!nolint</code> as the first lines, then a comment block with the version, commit link and license.</li><li>They are <strong>never edited or reformatted</strong>: the hook skips any <code>Vendor/</code> path, <code>.styluaignore</code> stops format-on-save, and <code>selene.toml</code> excludes them.</li><li>Code never requires <code>Vendor/</code> directly. A <strong>re-export file</strong> next to it (<code>Keel/Trove.luau</code>, <code>KeelServer/Data/ProfileStore.luau</code>) is the path everyone uses, so swapping a library changes one file.</li><li>To update one: replace the file with a newer pinned copy, put the two directive lines back, and update its header.</li></ul><table tabindex="0"><thead><tr><th>Library</th><th>Where</th><th>Reached through</th></tr></thead><tbody><tr><td>Trove</td><td><code>Keel/Vendor/Trove.luau</code></td><td><code>Keel/Trove.luau</code></td></tr><tr><td>Packet</td><td><code>Keel/Vendor/Packet/</code></td><td><code>Keel/Packet.luau</code> (only Net uses it)</td></tr><tr><td>ProfileStore</td><td><code>KeelServer/Vendor/ProfileStore.luau</code></td><td><code>KeelServer/Data/ProfileStore.luau</code></td></tr><tr><td>Cmdr</td><td><code>KeelServer/Vendor/Cmdr/</code></td><td><code>KeelServer/Console/Cmdr.luau</code></td></tr></tbody></table><h2 id="keel-setup-plugin" tabindex="-1">Keel Setup plugin <a class="header-anchor" href="#keel-setup-plugin" aria-label="Permalink to &quot;Keel Setup plugin&quot;">​</a></h2><p><code>tools/KeelSetup.lua</code> is a local Studio plugin, owned by Keel and updated with it. Studio has no way to script Script Sync&#39;s connect, so the plugin automates everything around it:</p><ul><li>creates the six root Folders that are missing, never touching one that exists;</li><li>creates the optional <a href="#place-attributes">place attributes</a> with their defaults, only where they have no value;</li><li>shows a checklist of the Folders and the disk folder each one must be connected to.</li></ul><p>Install it once per computer by copying it into Studio&#39;s Plugins folder (Plugins tab, Plugins Folder) and restarting Studio. <code>keel.js new</code> prints this step. It is a convenience: a game works the same if you create the Folders by hand. See <a href="/Keel-Docs/getting-started/connect-studio">Connect Roblox Studio</a>.</p><p>The Folder list in the plugin must match <code>Docs/Systems/Boot and Folders.md</code>; change both together.</p><h2 id="code-layout-skill" tabindex="-1">Code layout skill <a class="header-anchor" href="#code-layout-skill" aria-label="Permalink to &quot;Code layout skill&quot;">​</a></h2><p>StyLua keeps blank lines but never adds them, so spacing between statement groups is a judgement rule: the <code>luau-layout</code> skill (<code>.claude/skills/luau-layout/SKILL.md</code>). Group statements by purpose, separate groups with one blank line, keep a guard clause apart from the work after it, and put a blank line before the final <code>return</code>.</p>',26)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
